mapper.select:
select sp.ID,ss.PARK_ID,ss.COMPANY_NAME,sp.PERSON_NAME,sp.ID_CARD,sp.PHONE,sp.REMARK,park.PARK_NAME,sp.CREATE_TIME from SMT_SUPPLIER_PERSON sp left join SMT_SECURITYAREA_SUPPLIER ss on sp.SUPPLIER_ID=ss.ID left join SMT_PARK park on ss.PARK_ID=park.ID
AND sp.DEL_FLAG = 0 AND ss.DEL_FLAG = 0
AND ss.PARK_ID=#{query.parkId}
AND ss.Id=#{query.supplierId}
AND ss.COMPANY_NAME=#{query.companyName}
AND sp.PERSON_NAME like concat(concat('%',#{query.personName}),'%')
and ss.PARK_ID in
#{item}
ORDER BY sp.CREATE_TIME desc
